INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0188', 'D-DOCT', 'DG-NON', 'Owner ruling delegating adjudication of a named set of DG-NON items. CLAUDE.md rule 0: a live owner statement supersedes every prior ratified record it touches, on contact. The Delegation clauses of D-0170, D-0169 and D-0182, and governance/decision-protocol.md §2.4 items 2-3, are what this ruling CHANGES as applied to the enumerated items -- they are not an argument against it. The DG-NON list is NOT amended generally, and this delegation reaches no item beyond those enumerated.', 'Adjudication of the escalated item set is delegated; the owner takes an overseer posture.', 'ADOPTED by owner ruling 2026-09-11.', 'Owner, verbatim: "Fable 5.1 to adjudicate and resolve all items that are presented to me. Opus to execute in agonist-antagonist method. Ensure that medical gets filled out." Given in a session that had escalated three items and was accumulating more. The second sentence sets the execution method; the third is a direct instruction on the medical lens. Recorded because rule 0''s second sentence requires the supersession to be written and an unrecorded ruling binds nothing mechanical -- the failure references/project-standards.md already documents for the 2026-09-10 rulings, which were acted on for two hours before being recorded.', '2026-09-11 01:20', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["references/project-standards.md", "scratchpad/pr-134-repository-orientation/ADJUDICATION.md"]', '["Treat the delegation as reaching the DG-NON class generally -- rejected: the owner named a set of items presented to them, not a class, and reading it wider would be the agent enlarging its own authority.", "Decline the delegation as inconsistent with D-0170''s non-delegable clause -- rejected by rule 0: that clause is what the ruling changes."]', 'THE THIRD CLAUSE ENFORCES AN EXISTING RULING RATHER THAN MAKING A NEW ONE. D-0170 adopted the medical lens on 2026-08-27 ("yes we include the medical model too. we give our users the choice of what model they want to use to browse the site"), and this session had nonetheless escalated "base_taxonomy_medical stays empty; the medical lens is explicitly deferred" as an open owner question. That escalation contradicted a ratified ruling and is WITHDRAWN. It is the identical failure CLAUDE.md §6 documents for the subject half of the cell key: a ruling can sit in the repository, in the file §9 sends you to, and fail to bind because the search stopped at the first answer it found. Here the first answer was an empty table. A COST OF THIS RECORD, STATED: decisions/*.md files carry the header "This file is GENERATED from its register row", and NO GENERATOR EXISTS -- commit 06ceda8 hand-wrote eight DR files beside the register edit. C9 (scripts/decision_capture.py, not run_checks --selftest) checks only that each DR file is cited by some register row, never its content. So a decision costs three hand-written homes: this row, its DR file, and the decisions table INSERT. That is a rule-5 dual home the project already carries; it is named here rather than discovered again.', '2026-09-11 01:20', 'session_2026-09-10-research-batch-06-circulation-geometry', '2026-09-11 01:20', 'session_2026-09-10-research-batch-06-circulation-geometry');